-- HQ reusable server-side product authority guard and certification probe.
create or replace function public.hq_assert_product_enabled(p_product_key text,p_policy_key text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v jsonb;begin v:=public.hq_evaluate_policy(p_product_key,p_policy_key,jsonb_build_object('surface','server_guard'));if coalesce((v->'value')::boolean,false)=false then raise exception 'PRODUCT_DISABLED:%',p_product_key using errcode='P0001';end if;return v;end $$;
revoke all on function public.hq_assert_product_enabled(text,text) from public,anon;
grant execute on function public.hq_assert_product_enabled(text,text) to authenticated;
create or replace function public.hq_certify_product_policy(p_product_key text,p_policy_key text,p_expected jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_eval jsonb;v_state hq_product_policy_state%rowtype;begin perform public.hq_assert_owner();v_eval:=public.hq_evaluate_policy(p_product_key,p_policy_key,jsonb_build_object('surface','certification'));select * into v_state from hq_product_policy_state where product_key=p_product_key and policy_key=p_policy_key;return jsonb_build_object('product',p_product_key,'policy',p_policy_key,'expected',p_expected,'evaluated',v_eval->'value','matches',v_eval->'value' is not distinct from p_expected,'state',coalesce(v_state.state,'unpublished'),'failureMode',v_eval->>'failureMode','decisionId',v_eval->>'decisionId','version',v_eval->>'version');end $$;
revoke all on function public.hq_certify_product_policy(text,text,jsonb) from public,anon;
grant execute on function public.hq_certify_product_policy(text,text,jsonb) to authenticated;
